(7569843, 1215233, 65234, '<td valign="top">Pretty scene. On my screen it looks oversaturated, the shadows have very little detail, and the sharp parts look oversharpened. Could be me.</td>', 'Pretty scene. On my screen it looks oversaturated, the shadows have very little detail, and the sharp parts look oversharpened. Could be me.', '2018-06-01 10:00:20.000000', NULL, 1),
(7569853, 1214812, 67258, '<td valign="top">This looks to be the archetypal British Army retired officer of fairly recent yesteryear.  Except the nerd in me doesn''t recognise the mess dress, which makes me think he may be a Commonwealth country RO.  None the less, a fine portrait.</td>', 'This looks to be the archetypal British Army retired officer of fairly recent yesteryear.  Except the nerd in me doesn''t recognise the mess dress, which makes me think he may be a Commonwealth country RO.  None the less, a fine portrait.', '2018-06-01 10:55:24.000000', NULL, 1),
