(7569967, 1215172, 59737, '<td valign="top">Nice macro, a little deeper depth of field would have helped this for me, like the green out of focus area in the back, brings the image together nicely.</td>', 'Nice macro, a little deeper depth of field would have helped this for me, like the green out of focus area in the back, brings the image together nicely.', '2018-06-01 22:39:46.000000', NULL, 1),
(7569968, 1214687, 59737, '<td valign="top">nicely captured, like how the image draws you in with the action in front and MBS in the background, has a golden ratio feel to it.  I have fond memories of time in Singapore.</td>', 'nicely captured, like how the image draws you in with the action in front and MBS in the background, has a golden ratio feel to it.  I have fond memories of time in Singapore.', '2018-06-01 22:41:43.000000', NULL, 1),
